    let mut p: *mut c_uchar = ::core::ptr::null_mut::<c_uchar>();
    let mut b22: c_uchar = 0;
    let mut w22: c_uchar = 0;
    let mut demerit: c_int = 0 as c_int;
    p = frame
        .offset(width as isize)
        .offset(1 as c_int as isize);
