                & *p.offset(-(1 as c_int) as isize) as c_int
                & *p.offset(-width as isize) as c_int
                & *p.offset((-width - 1 as c_int) as isize) as c_int)
                as c_uchar;
            w22 = (*p.offset(0 as c_int as isize) as c_int
                | *p.offset(-(1 as c_int) as isize) as c_int
                | *p.offset(-width as isize) as c_int
                | *p.offset((-width - 1 as c_int) as isize) as c_int)
                as c_uchar;
